// Returns the maximum value contained in a non-empty slice.
// Precondition: a.len() >= 1
pub fn max_array(a: &[i32]) -> i32 {
    let mut m = a[0];
    for &x in &a[1..] {
        if x > m {
            m = x;
        }
    }
    m
}

